/// <reference path="../../index.d.ts" />
import type { PublicLitElement as LitElement } from "@arcgis/lumina";
import type { ComboboxChildElement } from "../calcite-combobox/types.js";

declare module "@arcgis/lumina" {
export interface DeclareCssProperties {
  /** Specifies the component's text color. */
  "--calcite-combobox-item-group-text-color": "*";
  /** Specifies the component's border color. */
  "--calcite-combobox-item-group-border-color": "*";
}
}

/** @slot  - A slot for adding `calcite-combobox-item`s. */
export abstract class ComboboxItemGroup extends LitElement {
  /** Specifies the parent and grandparent `calcite-combobox-item`s, which are set on `calcite-combobox`. */
  accessor ancestors: ComboboxChildElement[] | undefined;
  /**
   * Specifies an accessible label for the component.
   *
   * @required
   */
  accessor label: string;
  /**
   * Specifies the group's position in the `calcite-combobox` menu.
   *
   * @default 0
   * @internal
   */
  accessor position: number;
}